if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();seller_request_payout($seller,(float)$_POST['amount'],trim((string)$_POST['method']),trim((string)$_POST['account']));$msg='Payout request submitted.';}catch(Throwable $e){$err=$e->getMessage();}
$w=seller_wallet($seller);$reserved=(float)operations_scalar("SELECT COALESCE(SUM(amount),0) FROM seller_payout_requests WHERE seller_user_id=? AND status IN ('requested','approved','processing')",[$seller],0);$withdrawable=max(0,(float)$w['available_balance']-$reserved);$tx=operations_rows('SELECT * FROM seller_wallet_transactions WHERE seller_user_id=? ORDER BY id DESC LIMIT 100',[$seller]);$payouts=operations_rows('SELECT * FROM seller_payout_requests WHERE seller_user_id=? ORDER BY id DESC LIMIT 50',[$seller]);$sett=operations_rows('SELECT s.*,o.order_number FROM commerce_order_settlements s JOIN store_orders o ON o.id=s.order_id WHERE s.seller_user_id=? ORDER BY s.id DESC LIMIT 50',[$seller]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seller Finance - <?=e(setting('site_name','ShahkotPK'))?></title><link rel="stylesheet" href="/assets/shahkotpk-userdash-1.7.0.css"><link rel="stylesheet" href="/assets/operations-3.6.0.css"></head><body class="dashboard-page"><div class="dash-shell"><div class="dash-topbar"><a class="dash-back" href="/shopkeeper.php">← Seller Dashboard</a><div class="dash-actions"><a class="dash-chip" href="/shopkeeper-orders.php">Orders</a><a class="dash-chip" href="/seller-inventory.php">Inventory</a></div></div><section class="dash-hero"><div class="dash-hero-grid"><div><span class="dash-badge">COMMERCIAL FINANCE</span><h1>Seller Wallet & Payouts</h1><p>Track marketplace settlements and request payouts from your available balance.</p></div><div class="dash-hero-side"><div class="dash-mini-stat"><strong>Rs <?=e(number_format($withdrawable,0))?></strong><span>Withdrawable</span></div><div class="dash-mini-stat"><strong>Rs <?=e(number_format($reserved,0))?></strong><span>Pending Payouts</span></div><div class="dash-mini-stat"><strong>Rs <?=e(number_format((float)$w['lifetime_earnings'],0))?></strong><span>Lifetime Earnings</span></div><div class="dash-mini-stat"><strong>Rs <?=e(number_format((float)$w['lifetime_paid_out'],0))?></strong><span>Paid Out</span></div></div></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><div class="ops-grid"><section class="ops-card"><h2>Request Payout</h2><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="number" step="0.01" name="amount" placeholder="Amount" required><select name="method"><option value="bank">Bank Transfer</option><option value="jazzcash">JazzCash</option><option value="easypaisa">Easypaisa</option></select><input name="account" placeholder="IBAN / account / wallet number" required><button class="btn">Request Payout</button></form><p class="ops-muted">Minimum: Rs <?=e(number_format((float)setting('seller_min_payout','1000'),0))?></p></section><section class="ops-card"><h2>Settlement Rule</h2><p>Paid orders are credited after delivery/completion. Platform commission is deducted automatically before seller wallet credit.</p></section></div><section class="dash-card"><h2>Recent Payouts</h2><div class="ops-table"><table><tr><th>Payout</th><th>Amount</th><th>Net</th><th>Method</th><th>Status</th></tr><?php foreach($payouts as $r):?><tr><td><?=e($r['payout_number'])?></td><td>Rs <?=e(number_format((float)$r['amount'],0))?></td><td>Rs <?=e(number_format((float)$r['net_amount'],0))?></td><td><?=e($r['payout_method'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div></section><section class="dash-card"><h2>Wallet Transactions</h2><div class="ops-table"><table><tr><th>Date</th><th>Type</th><th>Amount</th><th>Balance</th><th>Description</th></tr><?php foreach($tx as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['transaction_type'])?></td><td>Rs <?=e(number_format((float)$r['amount'],0))?></td><td>Rs <?=e(number_format((float)$r['balance_after'],0))?></td><td><?=e($r['description'])?></td></tr><?php endforeach;?></table></div></section></div></body></html>
